<?php
require 'includes/bootstrap.php'; require_admin(); redirect('dashboard.php'); require 'includes/layout.php';
$stats = [];
foreach (['bookings','customers','hotels','vehicles'] as $table) $stats[$table] = (int)db()->query("SELECT COUNT(*) FROM $table")->fetchColumn();
$revenue = (float)db()->query("SELECT COALESCE(SUM(total_amount),0) FROM bookings WHERE status IN ('confirmed','completed')")->fetchColumn();
$recent = db()->query("SELECT b.*, c.full_name FROM bookings b LEFT JOIN customers c ON c.id=b.customer_id ORDER BY b.created_at DESC LIMIT 6")->fetchAll();
$statusData = db()->query("SELECT status, COUNT(*) total FROM bookings GROUP BY status")->fetchAll();
page_header('Good afternoon, ' . explode(' ', admin()['name'])[0]); ?>
<section class="hero"><div><p class="eyebrow">TODAY'S SNAPSHOT</p><h2>Your travel business,<br>at a glance.</h2><p>Manage what appears in the app and keep every reservation moving.</p></div><div class="hero-orbit"><span>✈</span></div></section>
<section class="stat-grid"><article class="stat"><div class="stat-icon purple">☷</div><div><p>Total bookings</p><strong><?= number_format($stats['bookings']) ?></strong><small>All-time reservations</small></div></article><article class="stat"><div class="stat-icon orange">$</div><div><p>Confirmed revenue</p><strong>$<?= number_format($revenue, 0) ?></strong><small>Confirmed & completed</small></div></article><article class="stat"><div class="stat-icon teal">♙</div><div><p>Customers</p><strong><?= number_format($stats['customers']) ?></strong><small>Traveler profiles</small></div></article><article class="stat"><div class="stat-icon pink">◇</div><div><p>Active inventory</p><strong><?= $stats['hotels'] + $stats['vehicles'] ?></strong><small>Hotels and vehicles</small></div></article></section>
<section class="dashboard-grid"><article class="panel span-2"><div class="panel-head"><div><p class="eyebrow">RECENT ACTIVITY</p><h3>Latest bookings</h3></div><a href="bookings.php">View all →</a></div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Guest</th><th>Service</th><th>Total</th><th>Status</th></tr></thead><tbody><?php foreach($recent as $row): ?><tr><td><strong><?= e($row['booking_code']) ?></strong><small><?= date('M j, Y', strtotime($row['created_at'])) ?></small></td><td><?= e($row['full_name'] ?? 'Guest') ?></td><td><?= e(ucfirst($row['booking_type'])) ?></td><td>$<?= number_format((float)$row['total_amount'],2) ?></td><td><span class="badge <?= e($row['status']) ?>"><?= e($row['status']) ?></span></td></tr><?php endforeach; ?><?php if(!$recent): ?><tr><td colspan="5" class="empty">No bookings yet.</td></tr><?php endif; ?></tbody></table></div></article><article class="panel"><div class="panel-head"><div><p class="eyebrow">WORKFLOW</p><h3>Booking status</h3></div></div><div class="status-list"><?php foreach($statusData as $s): ?><div><span class="status-dot <?= e($s['status']) ?>"></span><label><?= e(ucfirst($s['status'])) ?></label><strong><?= (int)$s['total'] ?></strong></div><?php endforeach; ?><?php if(!$statusData): ?><p class="empty">No activity yet.</p><?php endif; ?></div><a href="bookings.php" class="btn secondary wide">Manage bookings</a></article></section>
<?php page_footer();
